INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1022619-mgt311', 'stk-user2838', 'MGT 311', 'info', '{"desc": "mgt 311\n\nمادة تتناول القانون التجاري السعودي … ( المادة بالعربي )\n\nو تتضمن … ( تاريخ القانون - المقارنة بالقانون الفرنسي و الألماني ) << سهالات 🙂\n\nالمادة متوسطة إلى سهله …\n\nتعتمد على الحفظ بشكل أساسي … إذا كان حفظك كويس حتكون المادة سهله جدا …\n\nسلبية المادة الوحيدة أنها مملة نوعا ما … لذلك المادة جدا مناسبة لفترة الصيف …\n\nأختم أخيرا بنقطة حول الدكاترة … المادة تدرس عادة من دكتورين … ( مكاوي - الجيلي )\n\nمكاوي ممتاز و الجيلي كويس …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311-legal-environment/120988/2", "user": "user2838", "ts": 1334457418000, "tid": 120988, "pn": 2}}', 1334457418000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1076867-mgt311', 'stk-abo.saud', 'MGT 311', 'info', '{"desc": "تتكلم عن الاعمال التجارية والتجار\nانواع الشركات بالتفصيل الممل من انشاءها الى الانقضاء\nتتكلم عن الاوراق التجارية مثل الكمبيالة والسندات والشيك بالتفصيل\nالمادة مفيدة جدا جدا وممتعة وتمس الواقع\nاخذتها مع الجيلي وكان شرحه ممتاااااااز", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311-legal-environment/120988/3", "user": "abo.saud", "ts": 1344273038000, "tid": 120988, "pn": 3}}', 1344273038000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1087703-mgt311', 'stk-s.a.l.m.a.n', 'MGT 311', 'info', '{"desc": "* الماده تتكلم عن القانون التجاري السعودي\n\n* يبدأ بشرح تاريخ القانون وبدايته , ثم يبدأ بالتعمق في التاجر وما له وما عليه والاوراق التجاريه ثم الى انواع الشركات ونشأتها وحقوقها واغلاقها وما الى ذلك\n\n* المادهـ تدرس طبعا باللغة العربيه بحكم انها تتحدث عن القانون السعودي\n\n* وجهة نظري ان الكتاب المستخدم سيء نوعا ما , تراه احيانا يكرر نفسه واحيانا \" يلخبط \" القارئ\n\n* الكورس يحتاج حفظ ومتابعه , واضاف لي الكثير من الاشياء الجديده بأمانهـ\n\n* اسئله الماده بيكون فيه اختيارات وصح وخطأ واسئله مقاليه , لكنها كلها تحتاج الى فهم وتفصيل وكل كلمة في السؤال لها معنى ومغزى وهدف\n\nاخيرا الكورس مو صعب ابد , شوية متابعه وبإذن الله قريد بطل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311-legal-environment/120988/4", "user": "S.a.l.m.a.n", "ts": 1346918281000, "tid": 120988, "pn": 4}}', 1346918281000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381440-mgt311', 'stk-user10207', 'MGT 311', 'info', '{"desc": "جودة المقرر بشكل عام\nالمقرر جيد ويتحدث عن القوانين والأنظمة التجارية والشركات والأوراق المالية والتجار والأعمال التجارية والأموال التجارية و في المملكة العربية السعودية.\n\nالمواضيع التي يغطيها المقررالفصل الأول / مقدمة، تعريف بالقانون التجاري ونطاقه وتطوره ومصادره.\nالفصل الثاني / الأعمال التجارية\nالفصل الثالث / التجار\nالفصل الرابع / الشركات التجارية\nالفصل الخامس / الأنواع المختلفة للشركات\nالفصل السادس / الأموال التجارية\nالفصل السابع / الأوراق التجارية\nالفصل الثامن / الكمبيالة\nالفصل التاسع / السند لأمر\nالفصل العاشر / الشيك\n\nأيضاً، المدرس يمكن يشرح حاجات ثانية لكن ليست في الإختبار مثل الغرف التجارية، حقوق الملكية، العلامات التجارية وغيرها.\n\nالكتاب المستخدم للمقرر\nإسم الكتاب: الوجيز في النظام التجاري السعودي، للدكتور سعيد يحيى.\nتقييم الكتاب:\n- الكتاب سيء من ناحية الإخراج ويوجد أخطاء مطبعية كثيرة كما أنه يكرر الكلام.\n- أيضاً الكتاب ليس منظم بشكل كافِ. فالتعاريف والقوانين والأمثلة تكون في فقرات مثل كتب العربي والإسلامي.\n- مشكلة أخرى وهي، أنه لا توجد أسئلة تقيس قراءة الطالب في نهاية الدرس.\n- على كل حال، توجد كتب ممتازة للقانون التجاري السعودي موجودة في مكتبة جرير، أتمنى من منسق المادة أنه يستبدله بأحد تلك الكتب.\n\nالأسئلة والأمثلة المستخدمة في المقررلا توجد أسئلة في الكتاب، والأمثلة لا بأس بها.\n\nمدى فائدته في الناحية التطبيقيةالمادة مهمة جداً لكل شخص يريد أن يعرف القوانين التجارية في المملكة. حيث أن القوانين توضع لحماية الشخص تجارياً أينما ذهب. أيضاً، المادة تشجع الطلاب بأن يقرأوا أكثر في القوانين التجارية بعد الإنتهاء من المادة.\n\nمواقع مهمة تفيدك في المادةموقع تداول\nموقع وزارة التجارة والصناعة\n(موقع الوزارة يحتوي على ملفات وصور بيانية رائعة مثل الصورة بالأسفل) تفيدك بالدراسة.\nhttp://s21.postimg.org/bakui4jp3/Company.png\n\nسهولة وصعوبة المادة\nمواضيع الميجر الأول والميجر الثاني أشوفها بسيطة، لكن في الفاينل لابد من المذاكرة.\n\nأسئلة متكررةماذا عن سهولة وصعوبة المادة؟\nالمادة أشوفها متوسطة إلى سهلة لأن المدرس سهلها على الطلاب بشكل كبير، مع العلم أني ما كنت مركز كثير على هذي المادة. ماتيريل الميجر الأول والميجر الثاني وجزء من الفاينل كانوا سهلين. لكن الجزء من الفاينل الي هو “الأوراق المالية” كان يتكلم بالتفصيل عنها بشكل كبير.\n\nهل أنزلها إلكتف ولالا؟\nإذا تغير الكتاب (وارد جداً في السمسترات القادمة)، نعم. المادة ممتعة إذا حبيتها.\n\nطريقة مذاكرة المادة؟\nالمادة نظرية، فلذلك الكتاب والسلايدات والنوت هي طرق المذاكرة.\n\nما هي نوعية الأسئلة في الإختبارات؟\nمن خلال الأولد أكزام، والأختبارات الي اختبرتها، المياجر والفاينل تكون إختيارات من متعدد، وأسئلة مقالية. وبعض الأحيان صح وخطأ.\n\nماهو أسلوب المدرس في الشرح؟\nغالباً المدرسين لمثل هذه المادة يكون شرحهم عن طريق السلايدات أو المناقشة.\n\nمن هم مدرسي المادة غالباً؟\nالمدرسين هما د. مكاوي، ود. الجيلي.\nهنا روابط تقييم المدرسين.\nد. مكاوي http://skfupm.kfupm.edu.sa/vb/showthread.php?t=79183\nد. الجيلي http://skfupm.kfupm.edu.sa/vb/showthread.php?t=58460\n\nكم عدد ساعات المادة؟ Credit hours\n3 ساعات.\n\nروابط مهمةالسيلابس\nhttp://www.megafileupload.com/en/file/543643/Syllabus-Syllabus-doc.html\nملخص للكتاب “مهم”\nhttp://www.megafileupload.com/en/file/543644/Business-Law-Note-docx.html\n\nبالتوفيق للجميع إن شاء الله 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311-legal-environment/120988/6", "user": "user10207", "ts": 1403354866000, "tid": 120988, "pn": 6}}', 1403354866000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450292-mgt311', 'stk-icsstudent', 'MGT 311', 'info', '{"desc": "ما انصح بالمادة كالكتف\nالمادة فيها كمية حفظ هائلة هائلة بشكل غير طبيعي\nاذا ذاكرتك قوية خذها, غير كزه لاتنزلها\n\nولا تسمع كلام غيرك بخصوص المادة\nانا واحد قال لي انه جاب فيها قريد عالي ونزلتها بناءا على نصيحته\nوتفاجأت بكمية الحفظ العظيمة وغير ان القريدات ستاندر كل خمس درجات لتر قريد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311-legal-environment/120988/7", "user": "ICSStudent", "ts": 1464105993000, "tid": 120988, "pn": 7}}', 1464105993000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473510-mgt311', 'stk-practice', 'MGT 311', 'info', '{"desc": "1- المادة فيها حفظ مو طبيعي ، تقسيمات واستثناءات وامثلة وحاجات تلحس المخ\n2- المادة ستاندرد مع مكاوي وما يرضى يخليها افرج ، اذا يهمك القريد لا تنزل معاه لان الجيلي ممكن يخليها افرج\n3- اسئلة مكاوي اصعب بكثير من اسئلة الجيلي بهذه المادة\n4- المادة راح تفيدك وتعرف انواع الشركات ونظامها بالسعودية\n5- كتاب المادة فاشل وخسارة لفلوس الجامعة انها تشتري كتاب فاشل زي هذا ( اخطاء نحوية بالهبل ) وصعوبة في الشرح\n6- افضل مصدر للمذاكرة هو سلايدات مكاوي\n7- المادة بالعربي لكن لا تحسبها زي العربي والاسلامي ، اذا عاملتها زي كذا فابشر بالـ C+ باحسن الأحوال ، الله لا يقول طبعا\n8- كلاس مكاوي ممتع لكن حقك بالملي ، كلاس الجيلي ممل لكن متساعد بالدرجات فالقرار لك ، انا جربتهم اثنينهم\n9- اذا ترمك مليان مواد حفظ ، لا تحطها معاهم خليها بأخر ترم اذا كنت طالب ادارة\n10- ميجر ون 70 سلايد وهو اسهل ميجر ، ميجر تو 130 سلايد ، الفاينل 90 سلايد ، طبعا حتحسها قليلة بس كل سلايد فيه كمية معلومات هائلة انا صراحة طول الترم وانا مستغرب من الشباب اللي يقولو سهلة مرة وحقت قريد ، العكس تماما تحتاج جهد زي اي مادة ثانية\n11- اعلى طالب بالمياجر طارت عليه الأي بلس والاي قبل الفاينل ، مع مكاوي طبعا ، مع الجيلي فيه طلاب باقي في رينج الاي بلس\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311-legal-environment/120988/8", "user": "Practice", "ts": 1495333191000, "tid": 120988, "pn": 8}}', 1495333191000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1475978-mgt311', 'stk-user9840', 'MGT 311', 'info', '{"desc": "المادة تتكلم عن القانون التجاري السعودي وكذلك عن شركات الاشخاص والاموال إلى آخره.\n\nالكورس فيه كمية حفظ تفر راسك فر .\nالكتاب سيء لأبعد درجة وكل الاعتماد على سلايدات مكاوي لكن راح تستفيد كثيرا من الكورس الصراحة وهو ممتع ايضا خصوصا مع مكاوي .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311-legal-environment/120988/9", "user": "user9840", "ts": 1499306919000, "tid": 120988, "pn": 9}}', 1499306919000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p744465-mgt311', 'stk-user4836', 'MGT 311', 'info', '{"desc": "أولا المادة بالعربي 😭\nثانيا: شغل حفظ احفظ المنهج و روح للاختبار.\nثالثا: الطيب الجيلي ما اقول سيء بس لو لقيت غيرو يكون افضلك.\nانا منزلها مع الجيلي هذا السمستر 10.1 😐\nالتحضير اول الكلاس و يحضر المتأخرين نهاية الكلاس بعد ما يعطيهم محاضرة ربع ساعة ليش متأخرين. 🥊 (كل حصة). و بعض الطلاب يحضرو أول الكلاس و يمشوا بعد 15 - 30 دقيقة. ❤️*\nالشرح من السلايدات. و المعلومات فيها رؤوس اقلام يعني ما يكفي تدرسها بس. 😞\nواجبات منزلية كل فترة يعني ممكن كل ثلاث مواضيع واحد\nالكويزات: حسب السلايدات. فجأة تلاقي سلايد فيها اسئلة و غالبا في نفس شرح الحصة\nانا اعطيه جريد C مو أكثر.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311/99274/2", "user": "user4836", "ts": 1292389740000, "tid": 99274, "pn": 2}}', 1292389740000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p744638-mgt311', 'stk-fahad-07', 'MGT 311', 'info', '{"desc": "ياخوي نزلها وانت مغمض عند مكااااااوي\n\nانسان فاهم الماده ومياجره سهله جدا جدا واخلاقه جدا رائعه لايوجد لديه كويزات\n\nيعطيك موضوع تقوم تشرحه او سوال تروح تحله وتجيب له الحل يعطيك عليه بونص\n\nمع الدكتور مكاوي الماده سهله جدا وماده قريد جدا\n\nبالتوووووفيق لك ان شاء اللهـ\n\nاعطي الدكتور a+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311/99274/4", "user": "Fahad-07", "ts": 1292416594000, "tid": 99274, "pn": 4}}', 1292416594000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p316508-mgt311', 'stk-brameg', 'MGT 311', 'info', '{"desc": "الجيلي حق c و c+\n\nفي حصة الدكتور الجيلي يمديك تسوي أشياء كثيرة\n\nمنها\n\n1- المذاكرة وقت الحصة\n\n2- النوم وقت المحـاضرة\n\n3- الخروج وقضاء الوقت عند الانترنت أو الأكل\n\n!\n\nالشرح لو فهمته بتجيب درجات حلوة لكن صعب جدا التركيز\nوالاختبار يعتمد على مذاكرتك الشخصية \" إذا لم تكن مركز في الحصة \"\n\nالأسئلة كـومن ودقيقة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt311/66657/3", "user": "brameg", "ts": 1223581450000, "tid": 66657, "pn": 3}}', 1223581450000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p112147-mgt311', 'stk-high_voltage', 'MGT 311', 'info', '{"desc": "اخي العزيز لم تذكر ماهو ضغط المواد عندك… يعني كم ساعه منزل الترم الجاي… و ماهو مستواك الدراسي و كيف انت في مواد الاداره بشكل عام… لكي نستطيع ان نعطيك نصيحه بمقاسك 🙂\n\nو على العموم المادة هي مادة القانون التجاري السعودي… هي مادة ثقيلة دم و هي المادة الوحيدة في كلية الادارة التي تدرس بالعربي… مادة محاميين و مادري ما نفعها للنا كطلاب تسويق او محاسبة او ايا كان…\nاسئلتها كلها صح و غلط لكن لا تستهين بها… لانه يجي الدكتور (الله يستر عليه) يغيرلك حرف في الجمله و اذا حطيت صح يقولك لأ في حرف غلط في الجمله… بس ابشرك الدكتور دا اخيرا مشي من الجامعه و الترم الي فات كان اخر ترم له في الجامعه بعد ما قضى مايقارب الـ 21 سنه في الكليه يدرس نفس المنهج كل ترم لـ 3 سكاشن… فلك ان تتخيل انه حافظ كل كلمه و جمله في الكتاب و يجي يسمعها لك في الحصه… و كل طلاب الاداره يشهدوا على كلامي… سواء الي درسها قبل سنه و لا قبل 15 سنه…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311/51728/2", "user": "High_Voltage", "ts": 1156083290000, "tid": 51728, "pn": 2}}', 1156083290000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1255910-mgt311', 'stk-azoooozy', 'MGT 311', 'info', '{"desc": "الجيلي ماشفت انه زي مايقولون في المنتدى !\n\nخذت معه الصيف اللي راح وطلعت بقريد ماكنت اتوقعه الحمد لله\n\nمع اني معيّد في المياجر والفاينل اكيد\n\nالجيلي نظامه خله يعرفك انشب له في الكلاس تعال بدري وحاول تبين له انك مهتم وفالك القريد الطيّب\n\n+الدكتور فاهم واغلب اسئلته من اللي يقوله حاول تخطط وتسأله وتناقشه لان بعض الكلام اللي يقوله راح تلقاه سؤال في الميجر\n\n+انا تخصصي هندسة+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311/143479/12", "user": "azoooozy", "ts": 1377604000000, "tid": 143479, "pn": 12}}', 1377604000000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p176531-mgt311', 'stk-abdul_991', 'MGT 311', 'info', '{"desc": "ما تقدر تنزلها لإنك لازم تكون سفمور واللي افهمه من كلامك انك فرشمان على العموم الدكتور الطيب الجيلي من اطيب الدكاتره اللي مروا علي بس المادة (غثيثة) شوي (لا شويتين)وانصحك انك تنزل مواد فيها لابات علشان تترتاح بالسيميستر العادي(يعني بحكم انك بتحول يمكنacct تكون جيدة بالصيف او ماث على حسب قدرتك ) …الله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-311/56932/2", "user": "abdul_991", "ts": 1182161382000, "tid": 56932, "pn": 2}}', 1182161382000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-icsstudent-mgt311', 'stk-icsstudent', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f98475", "n": "Dr. Elgaily Ahmed Eltayeb", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "mgt311 - t152\n\nالتحضير :\nكل كلاس ما يدقق على التاخير\n\nطريقة الشرح :\nنقاط يمشي عليها في السلايدات, المادة ماتحتاج الى فهم مجرد حفظ معلومات يقولها لك ولا زم تحفظها\nينكت احيانا ونكته جامدة\n\nالكويزات :\nمافي\n\nالمياجر:\nصح وخطا واختيار ورتن\nصعبة جدا من بين السطور في الكتاب\n\nالفاينلات :\nنفس المياجر لكن اصعب والمنهج اطول وفي تشابه كبيير في محتوى الاختبار النهائي\n\nالصوت:\nواضح\n\nإضافات :\n\nالدكتور طيب مع الطلاب ومتساهل معانا بشكل عام\n\nتوزيع الدرجات ستاندر كل خمس درجات لتر قريد ما ادري عن الدكاترة الثانيين\n\nمتساهل جدا في تصحيح الرتن\n\nما انصح بالمادة كالكتف بسبب ان المادة فيها حفظ كثير والقريدات ستاندر\n\nلكن الدكتور نفسه - يعني لو في مادة غير هذي المادة - يعتبر ممتاز وحبيب ونكتي وما يغلط في مزحه على احد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450295-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-elgaily-ahmed-eltayeb/98475/13", "user": "ICSStudent", "ts": 1464106721000, "tid": 98475, "pn": 13}}]}', 1464106721000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-creative-guy-mgt311', 'stk-creative-guy', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f118714", "n": "Dr. Makkawi Mohammed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بالأسفل … رابط لقريدات الدكتور … فيه فقط 3 طلاب جابوا +C والباقي B ووفوق 🙂\n\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=99259\n\nالتحضير : يوميا ويهتم فيه بشكل كبير\nطريقة الشرح : يشرح باستخدام السلايدات, شرح واضح ومفهوم, وإذا كانت نقطة مش مفهومة يرجع يشرحها أكثر من مرة.\nالكويزات : لايوجد\nالمياجر: ميجر1 + ميجر2 كانت اسئلته خاصة فيه وكانت سهلة جدا\nالفاينلات : الفاينل كان أسهل من المياجر وكان مركز فيه عن موضوع “الشيك” في كورس mgt311\nالقريد النهائي: +A يستحقها وبكل جدارة…\nالصوت: مسموع وواضح\nإضافات : دكتور يحرجك بأخلاقه وطيبته.\nعملنا برفقته زيارة إلى المحكمة الإدارية كـ نشاط متعلق بالكورس + عملنا محكمة صورية بالكلاس.\n\nفي الأخير ما أقول إلا \" الله يذكرك بالخير يادكتور مكاوي\"", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1169280-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-makkawi-mohammed/118714/8", "user": "creative-guy", "ts": 1359137067000, "tid": 118714, "pn": 8}}]}', 1359137067000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-mgt311', 'stk-practice', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f118714", "n": "Dr. Makkawi Mohammed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تقييمي له بأخر الترم ، مجرد اضافة على النقاط السابقة\n\nMGT311 - Term 162\n\n1- مياجره بشكل عام متوسطة لكن فيه اسئلة صعبة وسهل جدا تخطيء فيها ، راح تعرف الشي ذا لما تشوف درجتك لكن وانت تحل حتحسه سهل\n2- الهايست بالمياجر طارت عليه الاي والاي بلس قبل الفاينل\n3- اعطانا هوموركين يقول بونس والله أعلم\n4- الفاينل كان اسهل من المياجر ولكن طويل نسبيا ، 70 سؤال صح وخطأ\n5- ما انصح فيه اذا تبغى قريد عالي\n6- احيانا يتصرف تصرفات مالها داعي، يبدأ يحضر 8:59 يعني قبل الكلاس واللي يدخل بعد كذا غايب\n7- الرجال فاهم القانون تمام ومو هين ، لا تستهين فيه وتحسبه بيسلكلك بالمادة\n8- احيانا يخلي الكلاس كامل سواليف والدكتور قريب من الطلاب مو زي باقي اغلب الدكاترة يشرح ويمشي\n\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473511-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-makkawi-mohammed/118714/12", "user": "Practice", "ts": 1495334050000, "tid": 118714, "pn": 12}}]}', 1495334050000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-mgt311', 'stk-user9840', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f118714", "n": "Dr. Makkawi Mohammed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 311 Term 162\n\nالتحضير : آخر دقيقة من الكلاس\nطريقة الشرح :يشرح من السلايدات ويشطح كثير وكلاسه ممتع وماتحس الصراحة بالكورس معه لايفوت.\nالكويزات : لايوجد\nالمياجر:سهل ممتنع بما معناه تريك لمن تقول آمين ،50 فقرة صح وخطا\nالفاينلات : كان سهل 70 فقرة صح وخطا\nالقريد النهائي: A+ ويستاهل اكثر\nالصوت: ممتاز\nإضافات :\n\nاغلب الطلاب بعد الميجر الثاني طارت عليهم A و A+ لكن اعتقد انه دف الطلاب لان فيه طلاب حصلوا A 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475981-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-makkawi-mohammed/118714/13", "user": "user9840", "ts": 1499308152000, "tid": 118714, "pn": 13}}]}', 1499308152000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mlekon-mgt311', 'stk-mlekon', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f118714", "n": "Dr. Makkawi Mohammed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT311-201 (تعليم عن بعد)\nالتحضير : بداية الكلاس وماكان يدقق على التأخير مره الي متأخر يجيه نهاية الكلاس ويحضره\nطريقة الشرح : سلايدات مرتبه (ما تحتاج الكتاب) شرحه كويس والرجال فاهم\nالكويزات : سهله كان معطينا زي قضية وتعطي رأيك فيها وماكان يدقق في التصحيح فيعطي درجات حلوه\nالمياجر: استبدلها باسايمنتات\nالفاينلات :صح وخطأ وخيارات ما كانت صعبه\nالقريد النهائي: A\nالصوت: ممتاز\nإضافات : الدكتور رهيب واخلاق لكن مشكلت مشغول جدا في غير التدريس فتحس انك ضايع ما فيه شي مرتب وواضح\nلكن ميزته في النهاية يضبطك بقريد حلو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529329-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-makkawi-mohammed/118714/14", "user": "MLEKON", "ts": 1617518073000, "tid": 118714, "pn": 14}}]}', 1617518073000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faris_alali-mgt311', 'stk-faris_alali', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f179107", "n": "Dr. Rakan Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT311-181\n\nالتحضير : نهاية المحاضرة و ما يكلمك إذا دخلت متأخر ربع ساعة و فوق , لكن بينبهك وهو يحضر و بيعطيك متأخر\nا\nالشرح : الدكتور زي ما كتبوا الشبيبة روحه شبابية و محاضراته ممتعة خصوصا إن المادة قانون و فيها أشياء جديدة , يعتمد اعتماد كلي على البوربوينت و المذاكرة بتكون منها\n\nالكيزات : عطانا ثلاث كويزات و أخذ افضل اثنين (معظم الطلاب كامل) , و بتكون صح أو خطأ و خيارات و جدا بسيطة الاسئلة لأنها اسئلة فهم مو حفظ\n\nالميد و الفاينل : نفس طريطة الكويزات خيارات و صح أو خطأ لكن يحب يلعب و يخدع الطلاب في بعض الاسئلة لدرجة ماحد جاب كامل\n\nالصوت : واااااااضح\n\nملاحظات :\n- الدكتور يعشق المشاركة\n- فيه برزنتيشن عليه 7% لكنه سهالات\n\nاذا وقته يناسبك نزل عنده و استمتع بالكورس و المعلومات الي بتاخذها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504078-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/5", "user": "Faris_Alali", "ts": 1545774514000, "tid": 179107, "pn": 5}}]}', 1545774514000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-mgt311', 'stk-jafar_15', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f179107", "n": "Dr. Rakan Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 311 -181\n\nالتحضير :\nتحضير يومي نهاية الكلاس ، ويبنهك اذا كنت متأخر\nطريقة الشرح :\nشرح الدكتور على سلايداته ، ومايتطرق للكتاب من الاساس\nشرحه ممتاز\n\nالكويزات :\nفي الاساس كان كويز واحد ، لكن بعد درجات المدترم قرر يخليها 3 وياخذ احسن اثنين\n5 أسئلة ، صح وخطا أو خيارات ، وغالبا يخلط بينهم\n\nالمياجر :\nمدترم ، متوسط الصعوبة وغالبية صعوبته بسبب تركاته\n25 سؤال ، نفس نظام الكوزيات 15 خيارات ، 10 صح وخطأ\n\nالفاينلات :\nنفس الكلام في المدترم ينطبق عليه في الفاينل ونفس نظام التركات\n35 سؤال\n\nالصوت :\nواضح\n\nإضافات :\nالدكتور يقدس شي اسمه مشاركة، لدرجة ان البونص يعتمد عليه بشكل اساسي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504162-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/6", "user": "Jafar_15", "ts": 1545938377000, "tid": 179107, "pn": 6}}]}', 1545938377000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-mgt311', 'stk-_182', 'MGT 311', 'doc', '{"docs": [{"id": "stk-dr-f179107", "n": "Dr. Rakan Alharbi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT311-181\n\nالتحضير: آخر المحاضرة, مرن إلا مع الي يتأخر مرة, أصلًا تستحي تتأخر عند الدكتور راكان\nطريقة الشرح: باوربوينت, بعضه يكون مفصّل بالباوربوينت وبعضه رؤوس أقلام, والاثنين الدكتور يشرحهم بشكل واضح\nالكويزات: تصحيح للأخ اللي فوق, الأصل أن للدكتور كويزّين, بس بعد ما شاف أنّ درجات الكويز الأول نازلة قرر يضيف ثالث وياخذ درجة أفضل اثنين\nالمياجر: اختبار نصفي عبارة عن خيارات وصح وخطأ, مستواه سهل, لكن أهم شيئ لا تستعجل وركز بالسؤال\nالفاينلات: مثل النصفي\nالقريد النهائي: A+\nالصوت: واضح جدًّا\nإضافات:\n\nأنا أخذت مع الدكتور IAS212 من قبل وأخذت معه MGT311, الدكتور شرحه واضح, أخلاقه عالية و يشجع الطلاب على النقاش ويحب الاستماع إلى آراءهم, متفهّم عند الغياب والتأخير -إذا عندك عذر-, أنصح فيه كخيار بأول, بالذات بمادة MGT311, لا تفوّتونه!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1505268-mgt311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakan-alharbi/179107/7", "user": "_182", "ts": 1548264673000, "tid": 179107, "pn": 7}}]}', 1548264673000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
